window.__finlexDocLoaded(24,{"id":24,"articles":[{"id":657,"no":"第一条","heading":"","text":"为了规范套期会计处理，根据《企业会计准则——基本准则》，制定本准则。","seq":0,"links":[{"doc_id":15,"tier":"L3","score":64,"rel_kind":"cites","target_seq":2,"target_art_no":"第三条","dir":"in","note":"正文显式引用《企业会计准则第24号——套期会计》"},{"doc_id":19,"tier":"L3","score":64,"rel_kind":"cites","target_seq":2,"target_art_no":"第三条","dir":"in","note":"正文显式引用《企业会计准则第24号——套期会计》"},{"doc_id":22,"tier":"L3","score":64,"rel_kind":"cites","target_seq":5,"target_art_no":"第六条","dir":"in","note":"正文显式引用《企业会计准则第24号——套期会计》"},{"doc_id":22,"tier":"L3","score":64,"rel_kind":"cites","target_seq":27,"target_art_no":"第二十八条","dir":"in","note":"正文显式引用《企业会计准则第24号——套期会计》"},{"doc_id":22,"tier":"L3","score":64,"rel_kind":"cites","target_seq":36,"target_art_no":"第三十七条","dir":"in","note":"正文显式引用《企业会计准则第24号——套期会计》"},{"doc_id":22,"tier":"L3","score":64,"rel_kind":"cites","target_seq":63,"target_art_no":"第六十四条","dir":"in","note":"正文显式引用《企业会计准则第24号——套期会计》"},{"doc_id":22,"tier":"L3","score":64,"rel_kind":"cites","target_seq":66,"target_art_no":"第六十七条","dir":"in","note":"正文显式引用《企业会计准则第24号——套期会计》"},{"doc_id":25,"tier":"L3","score":64,"rel_kind":"cites","target_seq":3,"target_art_no":"第四条","dir":"in","note":"正文显式引用《企业会计准则第24号——套期会计》"},{"doc_id":30,"tier":"L3","score":64,"rel_kind":"cites","target_seq":55,"target_art_no":"第五十六条","dir":"in","note":"正文显式引用《企业会计准则第24号——套期会计》"},{"doc_id":38,"tier":"L3","score":64,"rel_kind":"cites","target_seq":17,"target_art_no":"第十八条","dir":"in","note":"正文显式引用《企业会计准则第24号——套期会计》"},{"doc_id":110,"tier":"L3","score":64,"rel_kind":"cites","target_seq":11,"target_art_no":"第12节","dir":"in","note":"正文显式引用《企业会计准则第24号——套期会计》"},{"doc_id":241,"tier":"L3","score":64,"rel_kind":"cites","target_seq":11,"target_art_no":"第12节","dir":"in","note":"正文显式引用《企业会计准则第24号——套期会计》"}]},{"id":658,"no":"第二条","heading":"","text":"套期，是指企业为管理外汇风险、利率风险、价格风险、信用风险等特定风险引起的风险敞口，指定金融工具为套期工具，以使套期工具的公允价值或现金流量变动，预期抵销被套期项目全部或部分公允价值或现金流量变动的风险管理活动。","seq":1},{"id":659,"no":"第三条","heading":"","text":"套期分为公允价值套期、现金流量套期和境外经营净投资套期。 公允价值套期，是指对已确认资产或负债、尚未确认的确定承诺，或上述项目组成部分的公允价值变动风险敞口进行的套期。该公允价值变动源于特定风险，且将影响企业的损益或其他综合收益。其中，影响其他综合收益的情形，仅限于企业对指定为以公允价值计量且其变动计入其他综合收益的非交易性权益工具投资的公允价值变动风险敞口进行的套期。 现金流量套期，是指对现金流量变动风险敞口进行的套期。该现金流量变动源于与已确认资产或负债、极可能发生的预期交易，或与上述项目组成部分有关的特定风险，且将影响企业的损益。 境外经营净投资套期，是指对境外经营净投资外汇风险敞口进行的套期。境外经营净投资，是指企业在境外经营净资产中的权益份额。 对确定承诺的外汇风险进行的套期，企业可以将其作为公允价值套期或现金流量套期处理。","seq":2,"links":[{"doc_id":112,"tier":"L1","score":96,"rel_kind":"companion","target_seq":2,"target_art_no":"第3节","dir":"in","note":"指南详解（第3节）：锚定第三条（权益工具、公允价值套期）"}]},{"id":660,"no":"第四条","heading":"","text":"对于满足本准则第二章和第三章规定条件的套期，企业可以运用套期会计方法进行处理。 套期会计方法，是指企业将套期工具和被套期项目产生的利得或损失在相同会计期间计入当期损益（或其他综合收益）以反映风险管理活动影响的方法。","seq":3},{"id":661,"no":"第五条","heading":"","text":"套期工具，是指企业为进行套期而指定的、其公允价值或现金流量变动预期可抵销被套期项目的公允价值或现金流量变动的金融工具，包括： （一）以公允价值计量且其变动计入当期损益的衍生工具，但签出期权除外。企业只有在对购入期权（包括嵌入在混合合同中的购入期权）进行套期时，签出期权才可以作为套期工具。嵌入在混合合同中但未分拆的衍生工具不能作为单独的套期工具。 （二）以公允价值计量且其变动计入当期损益的非衍生金融资产或非衍生金融负债，但指定为以公允价值计量且其变动计入当期损益、且其自身信用风险变动引起的公允价值变动计入其他综合收益的金融负债除外。 企业自身权益工具不属于企业的金融资产或金融负债，不能作为套期工具。","seq":4,"links":[{"doc_id":112,"tier":"L1","score":96,"rel_kind":"companion","target_seq":3,"target_art_no":"第4节","dir":"in","note":"指南详解（第4节）：锚定第五条（金融负债、权益工具）"},{"doc_id":224,"tier":"L1","score":94,"rel_kind":"companion","target_seq":12,"target_art_no":"问13","dir":"in","note":"实施问答（问13）：锚定第五条（金融负债、权益工具）"},{"doc_id":224,"tier":"L1","score":94,"rel_kind":"companion","target_seq":26,"target_art_no":"问27","dir":"in","note":"实施问答（问27）：锚定第五条（金融负债、权益工具）"},{"doc_id":253,"tier":"L5","score":44,"rel_kind":"applies_to","target_seq":1,"target_art_no":"案例2","dir":"in","note":"官方案例（案例2·对减资程序的考虑（2022））：锚定第五条（金融负债、权益工具）"},{"doc_id":253,"tier":"L5","score":44,"rel_kind":"applies_to","target_seq":2,"target_art_no":"案例3","dir":"in","note":"官方案例（案例3·中止和恢复回售权（2022））：锚定第五条（金融负债、权益工具）"},{"doc_id":253,"tier":"L5","score":44,"rel_kind":"applies_to","target_seq":3,"target_art_no":"案例4","dir":"in","note":"官方案例（案例4·补充协议导致发行人义务变化（2022））：锚定第五条（金融负债、权益工具）"},{"doc_id":253,"tier":"L5","score":44,"rel_kind":"applies_to","target_seq":4,"target_art_no":"案例5","dir":"in","note":"官方案例（案例5·发行人作为合同一方承担的义务（2022））：锚定第五条（金融负债、权益工具）"}]},{"id":662,"no":"第六条","heading":"","text":"对于外汇风险套期，企业可以将非衍生金融资产（选择以公允价值计量且其变动计入其他综合收益的非交易性权益工具投资除外）或非衍生金融负债的外汇风险成分指定为套期工具。","seq":5},{"id":663,"no":"第七条","heading":"","text":"在确立套期关系时，企业应当将符合条件的金融工具整体指定为套期工具，但下列情形除外： （一）对于期权，企业可以将期权的内在价值和时间价值分开，只将期权的内在价值变动指定为套期工具。 （二）对于远期合同，企业可以将远期合同的远期要素和即期要素分开，只将即期要素的价值变动指定为套期工具。 （三）对于金融工具，企业可以将金融工具的外汇基差单独分拆，只将排除外汇基差后的金融工具指定为套期工具。 （四）企业可以将套期工具的一定比例指定为套期工具，但不可以将套期工具剩余期限内某一时段的公允价值变动部分指定为套期工具。","seq":6},{"id":664,"no":"第八条","heading":"","text":"企业可以将两项或两项以上金融工具（或其一定比例）的组合指定为套期工具（包括组合内的金融工具形成风险头寸相互抵销的情形）。 对于一项由签出期权和购入期权组成的期权（如利率上下限期权），或对于两项或两项以上金融工具（或其一定比例）的组合，其在指定日实质上相当于一项净签出期权的，不能将其指定为套期工具。只有在对购入期权（包括嵌入在混合合同中的购入期权）进行套期时，净签出期权才可以作为套期工具。","seq":7},{"id":665,"no":"第九条","heading":"","text":"被套期项目，是指使企业面临公允价值或现金流量变动风险，且被指定为被套期对象的、能够可靠计量的项目。企业可以将下列单个项目、项目组合或其组成部分指定为被套期项目： （一）已确认资产或负债。 （二）尚未确认的确定承诺。确定承诺，是指在未来某特定日期或期间，以约定价格交换特定数量资源、具有法律约束力的协议。 （三）极可能发生的预期交易。预期交易，是指尚未承诺但预期会发生的交易。 （四）境外经营净投资。 上述项目组成部分是指小于项目整体公允价值或现金流量变动的部分，企业只能将下列项目组成部分或其组合指定为被套期项目： （一）项目整体公允价值或现金流量变动中仅由某一个或多个特定风险引起的公允价值或现金流量变动部分（风险成分）。根据在特定市场环境下的评估，该风险成分应当能够单独识别并可靠计量。风险成分也包括被套期项目公允价值或现金流量的变动仅高于或仅低于特定价格或其他变量的部分。 （二）一项或多项选定的合同现金流量。 （三）项目名义金额的组成部分，即项目整体金额或数量的特定部分，其可以是项目整体的一定比例部分，也可以是项目整体的某一层级部分。若某一层级部分包含提前还款权，且该提前还款权的公允价值受被套期风险变化影响的，企业不得将该层级指定为公允价值套期的被套期项目，但企业在计量被套期项目的公允价值时已包含该提前还款权影响的情况除外。","seq":8,"links":[{"doc_id":224,"tier":"L1","score":94,"rel_kind":"companion","target_seq":5,"target_art_no":"问6","dir":"in","note":"实施问答（问6）：锚定第九条（条文主题匹配）"},{"doc_id":224,"tier":"L1","score":94,"rel_kind":"companion","target_seq":7,"target_art_no":"问8","dir":"in","note":"实施问答（问8）：锚定第九条（条文主题匹配）"},{"doc_id":224,"tier":"L1","score":94,"rel_kind":"companion","target_seq":14,"target_art_no":"问15","dir":"in","note":"实施问答（问15）：锚定第九条（条文主题匹配）"},{"doc_id":224,"tier":"L1","score":94,"rel_kind":"companion","target_seq":29,"target_art_no":"问30","dir":"in","note":"实施问答（问30）：锚定第九条（条文主题匹配）"}]},{"id":666,"no":"第十条","heading":"","text":"企业可以将符合被套期项目条件的风险敞口与衍生工具组合形成的汇总风险敞口指定为被套期项目。","seq":9,"links":[{"doc_id":253,"tier":"L5","score":44,"rel_kind":"applies_to","target_seq":5,"target_art_no":"案例6","dir":"in","note":"官方案例（案例6·投资者保护条款（2022））：显式指向第10条"}]},{"id":667,"no":"第十一条","heading":"","text":"当企业出于风险管理目的对一组项目进行组合管理、且组合中的每一个项目（包括其组成部分）单独都属于符合条件的被套期项目时，可以将该项目组合指定为被套期项目。 在现金流量套期中，企业对一组项目的风险净敞口（存在风险头寸相互抵销的项目）进行套期时，仅可以将外汇风险净敞口指定为被套期项目，并且应当在套期指定中明确预期交易预计影响损益的报告期间，以及预期交易的性质和数量。","seq":10},{"id":668,"no":"第十二条","heading":"","text":"企业将一组项目名义金额的组成部分指定为被套期项目时，应当分别满足以下条件： （一）企业将一组项目的一定比例指定为被套期项目时，该指定应当与该企业的风险管理目标相一致。 （二）企业将一组项目的某一层级部分指定为被套期项目时，应当同时满足以下条件： 1．该层级能够单独识别并可靠计量。 2．企业的风险管理目标是对该层级进行套期。 3．该层级所在的整体项目组合中的所有项目均面临相同的被套期风险。 4．对于已经存在的项目（如已确认资产或负债、尚未确认的确定承诺）进行的套期，被套期层级所在的整体项目组合可识别并可追踪。 5．该层级包含提前还款权的，应当符合本准则第九条项目名义金额的组成部分中的相关要求。 本准则所称风险管理目标，是指企业在某一特定套期关系层面上，确定如何指定套期工具和被套期项目，以及如何运用指定的套期工具对指定为被套期项目的特定风险敞口进行套期。","seq":11},{"id":669,"no":"第十三条","heading":"","text":"如果被套期项目是净敞口为零的项目组合（即各项目之间的风险完全相互抵销），同时满足下列条件时，企业可以将该组项目指定在不含套期工具的套期关系中： （一）该套期是风险净敞口滚动套期策略的一部分，在该策略下，企业定期对同类型的新的净敞口进行套期； （二）在风险净敞口滚动套期策略整个过程中，被套期净敞口的规模会发生变化，当其不为零时，企业使用符合条件的套期工具对净敞口进行套期，并通常采用套期会计方法； （三）如果企业不对净敞口为零的项目组合运用套期会计，将导致不一致的会计结果，因为不运用套期会计方法将不会确认在净敞口套期下确认的相互抵销的风险敞口。","seq":12},{"id":670,"no":"第十四条","heading":"","text":"运用套期会计时，在合并财务报表层面，只有与企业集团之外的对手方之间交易形成的资产、负债、尚未确认的确定承诺或极可能发生的预期交易才能被指定为被套期项目；在合并财务报表层面，只有与企业集团之外的对手方签订的合同才能被指定为套期工具。对于同一企业集团内的主体之间的交易，在企业个别财务报表层面可以运用套期会计，在企业集团合并财务报表层面不得运用套期会计，但下列情形除外： （一）在合并财务报表层面，符合《企业会计准则第33号——合并财务报表》规定的投资性主体与其以公允价值计量且其变动计入当期损益的子公司之间的交易，可以运用套期会计。 （二）企业集团内部交易形成的货币性项目的汇兑收益或损失，不能在合并财务报表中全额抵销的，企业可以在合并财务报表层面将该货币性项目的外汇风险指定为被套期项目。 （三）企业集团内部极可能发生的预期交易，按照进行此项交易的主体的记账本位币以外的货币标价，且相关的外汇风险将影响合并损益的，企业可以在合并财务报表层面将该外汇风险指定为被套期项目。","seq":13,"links":[{"doc_id":224,"tier":"L1","score":94,"rel_kind":"companion","target_seq":20,"target_art_no":"问21","dir":"in","note":"实施问答（问21）：锚定第十四条（条文主题匹配）"},{"doc_id":224,"tier":"L1","score":94,"rel_kind":"companion","target_seq":31,"target_art_no":"问32","dir":"in","note":"实施问答（问32）：锚定第十四条（条文主题匹配）"},{"doc_id":33,"tier":"L3","score":64,"rel_kind":"cites","target_seq":0,"target_art_no":"第一条","dir":"out","note":"正文显式引用《企业会计准则第33号——合并财务报表》"},{"doc_id":253,"tier":"L5","score":44,"rel_kind":"applies_to","target_seq":0,"target_art_no":"案例1","dir":"in","note":"官方案例（案例1·资金集中管理会计处理应用案例（2022））：锚定第十四条（条文主题匹配）"}]},{"id":671,"no":"第十五条","heading":"","text":"公允价值套期、现金流量套期或境外经营净投资套期同时满足下列条件的，才能运用本准则规定的套期会计方法进行处理： （一）套期关系仅由符合条件的套期工具和被套期项目组成。 （二）在套期开始时，企业正式指定了套期工具和被套期项目，并准备了关于套期关系和企业从事套期的风险管理策略和风险管理目标的书面文件。该文件至少载明了套期工具、被套期项目、被套期风险的性质以及套期有效性评估方法（包括套期无效部分产生的原因分析以及套期比率确定方法）等内容。 （三）套期关系符合套期有效性要求。 套期有效性，是指套期工具的公允价值或现金流量变动能够抵销被套期风险引起的被套期项目公允价值或现金流量变动的程度。套期工具的公允价值或现金流量变动大于或小于被套期项目的公允价值或现金流量变动的部分为套期无效部分。","seq":14,"links":[{"doc_id":112,"tier":"L1","score":96,"rel_kind":"companion","target_seq":4,"target_art_no":"第5节","dir":"in","note":"指南详解（第5节）：锚定第十五条（公允价值套期、现金流量套期）"}]},{"id":672,"no":"第十六条","heading":"","text":"套期同时满足下列条件的，企业应当认定套期关系符合套期有效性要求： （一）被套期项目和套期工具之间存在经济关系。该经济关系使得套期工具和被套期项目的价值因面临相同的被套期风险而发生方向相反的变动。 （二）被套期项目和套期工具经济关系产生的价值变动中，信用风险的影响不占主导地位。 （三）套期关系的套期比率，应当等于企业实际套期的被套期项目数量与对其进行套期的套期工具实际数量之比，但不应当反映被套期项目和套期工具相对权重的失衡，这种失衡会导致套期无效，并可能产生与套期会计目标不一致的会计结果。例如，企业确定拟采用的套期比率是为了避免确认现金流量套期的套期无效部分，或是为了创造更多的被套期项目进行公允价值调整以达到增加使用公允价值会计的目的，可能会产生与套期会计目标不一致的会计结果。","seq":15,"links":[{"doc_id":224,"tier":"L1","score":94,"rel_kind":"companion","target_seq":9,"target_art_no":"问10","dir":"in","note":"实施问答（问10）：锚定第十六条（现金流量套期）"}]},{"id":673,"no":"第十七条","heading":"","text":"企业应当在套期开始日及以后期间持续地对套期关系是否符合套期有效性要求进行评估，尤其应当分析在套期剩余期限内预期将影响套期关系的套期无效部分产生的原因。企业至少应当在资产负债表日及相关情形发生重大变化将影响套期有效性要求时对套期关系进行评估。","seq":16,"links":[{"doc_id":224,"tier":"L1","score":94,"rel_kind":"companion","target_seq":28,"target_art_no":"问29","dir":"in","note":"实施问答（问29）：锚定第十七条（条文主题匹配）"}]},{"id":674,"no":"第十八条","heading":"","text":"套期关系由于套期比率的原因而不再符合套期有效性要求，但指定该套期关系的风险管理目标没有改变的，企业应当进行套期关系再平衡。 本准则所称套期关系再平衡，是指对已经存在的套期关系中被套期项目或套期工具的数量进行调整，以使套期比率重新符合套期有效性要求。基于其他目的对被套期项目或套期工具所指定的数量进行变动基于其他目的对被套期项目或套期工具所指定的数量进行调整，不构成本准则所称的套期关系再平衡。 企业在套期关系再平衡时，应当首先确认套期关系调整前的套期无效部分，并更新在套期剩余期限内预期将影响套期关系的套期无效部分产生原因的分析，同时相应更新套期关系的书面文件。","seq":17},{"id":675,"no":"第十九条","heading":"","text":"企业发生下列情形之一的，应当终止运用套期会计： （一）因风险管理目标发生变化，导致套期关系不再满足风险管理目标。 （二）套期工具已到期、被出售、合同终止或已行使。 （三）被套期项目与套期工具之间不再存在经济关系，或者被套期项目和套期工具经济关系产生的价值变动中，信用风险的影响开始占主导地位。 （四）套期关系不再满足本准则所规定的运用套期会计方法的其他条件。在适用套期关系再平衡的情况下，企业应当首先考虑套期关系再平衡，然后评估套期关系是否满足本准则所规定的运用套期会计方法的条件。 终止套期会计可能会影响套期关系的整体或其中一部分，在仅影响其中一部分时，剩余未受影响的部分仍适用套期会计。","seq":18},{"id":676,"no":"第二十条","heading":"","text":"套期关系同时满足下列条件的，企业不得撤销套期关系的指定并由此终止套期关系： （一）套期关系仍然满足风险管理目标； （二）套期关系仍然满足本准则运用套期会计方法的其他条件。在适用套期关系再平衡的情况下，企业应当首先考虑套期关系再平衡，然后评估套期关系是否满足本准则所规定的运用套期会计方法的条件。","seq":19},{"id":677,"no":"第二十一条","heading":"","text":"企业发生下列情形之一的，不作为套期工具已到期或合同终止处理： （一）套期工具展期或被另一项套期工具替换，而且该展期或替换是企业书面文件所载明的风险管理目标的组成部分。 （二）由于法律法规或其他相关规定的要求，套期工具的原交易对手方变更为一个或多个清算交易对手方（例如清算机构或其他主体），以最终达成由同一中央交易对手方进行清算的目的。如果存在套期工具其他变更的，该变更应当仅限于达成此类替换交易对手方所必须的变更。","seq":20},{"id":678,"no":"第二十二条","heading":"","text":"公允价值套期满足运用套期会计方法条件的，应当按照下列规定处理： （一）套期工具产生的利得或损失应当计入当期损益。如果套期工具是对选择以公允价值计量且其变动计入其他综合收益的非交易性权益工具投资（或其组成部分）进行套期的，套期工具产生的利得或损失应当计入其他综合收益。 （二）被套期项目因被套期风险敞口形成的利得或损失应当计入当期损益，同时调整未以公允价值计量的已确认被套期项目的账面价值。被套期项目为按照《企业会计准则第22号——金融工具确认和计量》第十八条分类为以公允价值计量且其变动计入其他综合收益的金融资产（或其组成部分）的，其因被套期风险敞口形成的利得或损失应当计入当期损益，其账面价值已经按公允价值计量，不需要调整；被套期项目为企业选择以公允价值计量且其变动计入其他综合收益的权益工具投资（或其组成部分）的，其因被套期风险敞口形成的利得或损失应当计入其他综合收益，其账面价值已经按公允价值计量，不需要调整。 被套期项目为尚未确认的确定承诺（或其组成部分）的，其在套期关系指定后因被套期风险引起的公允价值累计变动额应当确认为一项资产或负债，相关的利得或损失应当计入各相关期间损益。当履行确定承诺而取得资产或承担负债时，应当调整该资产或负债的初始确认金额，以包括已确认的被套期项目的公允价值累计变动额。","seq":21,"links":[{"doc_id":112,"tier":"L1","score":96,"rel_kind":"companion","target_seq":1,"target_art_no":"第2节","dir":"in","note":"指南详解（第2节）：锚定第二十二条（账面价值、公允价值套期）"},{"doc_id":112,"tier":"L1","score":96,"rel_kind":"companion","target_seq":5,"target_art_no":"第6节","dir":"in","note":"指南详解（第6节）：锚定第二十二条（账面价值、权益工具）"},{"doc_id":224,"tier":"L1","score":94,"rel_kind":"companion","target_seq":30,"target_art_no":"问31","dir":"in","note":"实施问答（问31）：锚定第二十二条（条文主题匹配）"},{"doc_id":22,"tier":"L3","score":72,"rel_kind":"cites","target_seq":17,"target_art_no":"第十八条","dir":"out","note":"正文显式引用《企业会计准则第22号——金融工具确认和计量》第18条"},{"doc_id":253,"tier":"L5","score":44,"rel_kind":"applies_to","target_seq":8,"target_art_no":"案例9","dir":"in","note":"官方案例（案例9·指定为以公允价值计量且其变动计入其他综合收益的权）：锚定第二十二条（账面价值、权益工具）"}]},{"id":679,"no":"第二十三条","heading":"","text":"公允价值套期中，被套期项目为以摊余成本计量的金融工具（或其组成部分）的，企业对被套期项目账面价值所作的调整应当按照开始摊销日重新计算的实际利率进行摊销，并计入当期损益。该摊销可以自调整日开始，但不应当晚于对被套期项目终止进行套期利得和损失调整的时点。被套期项目为按照《企业会计准则第22号——金融工具确认和计量》第十八条分类为以公允价值计量且其变动计入其他综合收益的金融资产（或其组成部分）的，企业应当按照相同的方式对累计已确认的套期利得或损失进行摊销，并计入当期损益，但不调整金融资产（或其组成部分）的账面价值。","seq":22,"links":[{"doc_id":224,"tier":"L1","score":94,"rel_kind":"companion","target_seq":22,"target_art_no":"问23","dir":"in","note":"实施问答（问23）：锚定第二十三条（条文主题匹配）"},{"doc_id":22,"tier":"L3","score":72,"rel_kind":"cites","target_seq":17,"target_art_no":"第十八条","dir":"out","note":"正文显式引用《企业会计准则第22号——金融工具确认和计量》第18条"},{"doc_id":22,"tier":"L3","score":72,"rel_kind":"cites","target_seq":41,"target_art_no":"第四十二条","dir":"in","note":"正文显式引用《企业会计准则第24号——套期会计》第23条"}]},{"id":680,"no":"第二十四条","heading":"","text":"现金流量套期满足运用套期会计方法条件的，应当按照下列规定处理： （一）套期工具产生的利得或损失中属于套期有效的部分，作为现金流量套期储备，应当计入其他综合收益。现金流量套期储备的金额，应当按照下列两项的绝对额中较低者确定： 1．套期工具自套期开始的累计利得或损失； 2．被套期项目自套期开始的预计未来现金流量现值的累计变动额。 每期计入其他综合收益的现金流量套期储备的金额应当为当期现金流量套期储备的变动额。 （二）套期工具产生的利得或损失中属于套期无效的部分（即扣除计入其他综合收益后的其他利得或损失），应当计入当期损益。","seq":23,"links":[{"doc_id":37,"tier":"L3","score":72,"rel_kind":"cites","target_seq":64,"target_art_no":"第六十五条","dir":"in","note":"正文显式引用《企业会计准则第24号——套期会计》第24条"}]},{"id":681,"no":"第二十五条","heading":"","text":"现金流量套期储备的金额，应当按照下列规定处理： （一）被套期项目为预期交易，且该预期交易使企业随后确认一项非金融资产或非金融负债的，或者非金融资产或非金融负债的预期交易形成一项适用于公允价值套期会计的确定承诺时，企业应当将原在其他综合收益中确认的现金流量套期储备金额转出，计入该资产或负债的初始确认金额。 （二）对于不属于本条（一）涉及的现金流量套期，企业应当在被套期的预期现金流量影响损益的相同期间，将原在其他综合收益中确认的现金流量套期储备金额转出，计入当期损益。 （三）如果在其他综合收益中确认的现金流量套期储备金额是一项损失，且该损失全部或部分预计在未来会计期间不能弥补的，企业应当在预计不能弥补时，将预计不能弥补的部分从其他综合收益中转出，计入当期损益。","seq":24,"links":[{"doc_id":224,"tier":"L1","score":94,"rel_kind":"companion","target_seq":2,"target_art_no":"问3","dir":"in","note":"实施问答（问3）：锚定第二十五条（条文主题匹配）"},{"doc_id":224,"tier":"L1","score":94,"rel_kind":"companion","target_seq":3,"target_art_no":"问4","dir":"in","note":"实施问答（问4）：锚定第二十五条（条文主题匹配）"},{"doc_id":37,"tier":"L3","score":72,"rel_kind":"cites","target_seq":68,"target_art_no":"第六十九条","dir":"in","note":"正文显式引用《企业会计准则第24号——套期会计》第25条"}]},{"id":682,"no":"第二十六条","heading":"","text":"当企业对现金流量套期终止运用套期会计时，在其他综合收益中确认的累计现金流量套期储备金额，应当按照下列规定进行处理： （一）被套期的未来现金流量预期仍然会发生的，累计现金流量套期储备的金额应当予以保留，并按照本准则第二十五条的规定进行会计处理。 （二）被套期的未来现金流量预期不再发生的，累计现金流量套期储备的金额应当从其他综合收益中转出，计入当期损益。预期不再极可能发生的被套期的未来现金流量预期仍然会发生的，累计现金流量套期储备的金额应当予以保留，并按照本准则第二十五条的规定进行会计处理。","seq":25,"links":[{"doc_id":224,"tier":"L1","score":94,"rel_kind":"companion","target_seq":16,"target_art_no":"问17","dir":"in","note":"实施问答（问17）：锚定第二十六条（条文主题匹配）"}]},{"id":683,"no":"第二十七条","heading":"","text":"对境外经营净投资的套期，包括对作为净投资的一部分进行会计处理的货币性项目的套期，应当按照类似于现金流量套期会计的规定处理： （一）套期工具形成的利得或损失中属于套期有效的部分，应当计入其他综合收益。 全部或部分处置境外经营时，上述计入其他综合收益的套期工具利得或损失应当相应转出，计入当期损益。 （二）套期工具形成的利得或损失中属于套期无效的部分，应当计入当期损益。","seq":26,"links":[{"doc_id":37,"tier":"L3","score":72,"rel_kind":"cites","target_seq":64,"target_art_no":"第六十五条","dir":"in","note":"正文显式引用《企业会计准则第24号——套期会计》第27条"}]},{"id":684,"no":"第二十八条","heading":"","text":"企业根据本准则第十八条规定对套期关系作出再平衡的，应当在调整套期关系之前确定套期关系的套期无效部分，并将相关利得或损失计入当期损益。 套期关系再平衡可能会导致企业增加或减少指定套期关系中被套期项目或套期工具的数量。企业增加了指定的被套期项目或套期工具的，增加部分自指定增加之日起作为套期关系的一部分进行处理；企业减少了指定的被套期项目或套期工具的，减少部分自指定减少之日起不再作为套期关系的一部分，作为套期关系终止处理。","seq":27},{"id":685,"no":"第二十九条","heading":"","text":"对于被套期项目为风险净敞口的套期，被套期风险影响利润表不同列报项目的，企业应当将相关套期利得或损失单独列报，不应当影响利润表中与被套期项目相关的损益列报项目金额（如营业收入或营业成本）。 对于被套期项目为风险净敞口的公允价值套期，涉及调整被套期各组成项目账面价值的，企业应当对各项资产和负债的账面价值做相应调整。","seq":28},{"id":686,"no":"第三十条","heading":"","text":"除本准则第二十九条规定外，对于被套期项目为一组项目的公允价值套期，企业在套期关系存续期间，应当针对被套期项目组合中各组成项目，分别确认公允价值变动所引起的相关利得或损失，按照本准则第二十二条的规定进行相应处理，计入当期损益或其他综合收益。涉及调整被套期各组成项目账面价值的，企业应当对各项资产和负债的账面价值做相应调整。 除本准则第二十九条规定外，对于被套期项目为一组项目的现金流量套期，企业在将其他综合收益中确认的相关现金流量套期储备转出时，应当按照系统、合理的方法将转出金额在被套期各组成项目中分摊，并按照本准则第二十五条的规定进行相应处理。","seq":29},{"id":687,"no":"第三十一条","heading":"","text":"企业根据本准则第七条规定将期权的内在价值和时间价值分开，只将期权的内在价值变动指定为套期工具时，应当区分被套期项目的性质是与交易相关还是与时间段相关。被套期项目与交易相关的，对其进行套期的期权时间价值具备交易成本的特征；被套期项目与时间段相关的，对其进行套期的期权时间价值具备为保护企业在特定时间段内规避风险所需支付成本的特征。企业应当根据被套期项目的性质分别进行以下会计处理： （一）对于与交易相关的被套期项目，企业应当按照本准则第三十二条的规定，将期权时间价值的公允价值变动中与被套期项目相关的部分计入其他综合收益。对于在其他综合收益中确认的期权时间价值的公允价值累计变动额，应当按照本准则第二十五条规定的与现金流量套期储备金额相同的会计处理方法进行处理。 （二）对于与时间段相关的被套期项目，企业应当按照本准则第三十二条的规定，将期权时间价值的公允价值变动中与被套期项目相关的部分计入其他综合收益。同时，企业应当按照系统、合理的方法，将期权被指定为套期工具当日的时间价值中与被套期项目相关的部分，在套期关系影响损益或其他综合收益（仅限于企业对指定为以公允价值计量且其变动计入其他综合收益的非交易性权益工具投资的公允价值变动风险敞口进行的套期）的期间内摊销，摊销金额从其他综合收益中转出，计入当期损益。若企业终止运用套期会计，则其他综合收益中剩余的相关金额应当转出，计入当期损益。 期权的主要条款（如名义金额、期限和标的）与被套期项目相一致的，期权的实际时间价值与被套期项目相关；期权的主要条款与被套期项目不完全一致的，企业应当通过对主要条款与被套期项目完全一致的期权进行估值确定校准时间价值，并确认期权的实际时间价值中与被套期项目相关的部分。","seq":30},{"id":688,"no":"第三十二条","heading":"","text":"在套期关系开始时，期权的实际时间价值高于校准时间价值的，企业应当以校准时间价值为基础，将其累计公允价值变动计入其他综合收益，并将这两个时间价值的公允价值变动差额计入当期损益；在套期关系开始时，期权的实际时间价值低于校准时间价值的，企业应当将两个时间价值中累计公允价值变动的较低者计入其他综合收益，如果实际时间价值的累计公允价值变动扣减累计计入其他综合收益金额后尚有剩余的，应当计入当期损益。","seq":31},{"id":689,"no":"第三十三条","heading":"","text":"企业根据本准则第七条规定将远期合同的远期要素和即期要素分开、只将即期要素的价值变动指定为套期工具的，或者将金融工具的外汇基差单独分拆、只将排除外汇基差后的金融工具指定为套期工具的，可以按照与期权时间价值相同的处理方式对远期合同的远期要素或金融工具的外汇基差进行会计处理。","seq":32,"links":[{"doc_id":224,"tier":"L1","score":94,"rel_kind":"companion","target_seq":4,"target_art_no":"问5","dir":"in","note":"实施问答（问5）：显式指向第33条"}]},{"id":690,"no":"第三十四条","heading":"","text":"企业使用以公允价值计量且其变动计入当期损益的信用衍生工具管理金融工具（或其组成部分）的信用风险敞口时，可以在该金融工具（或其组成部分）初始确认时、后续计量中或尚未确认时，将其指定为以公允价值计量且其变动计入当期损益的金融工具，并同时作出书面记录，但应当同时满足下列条件： （一）金融工具信用风险敞口的主体（如借款人或贷款承诺持有人）与信用衍生工具涉及的主体相一致； （二）金融工具的偿付级次与根据信用衍生工具条款须交付的工具的偿付级次相一致。 上述金融工具（或其组成部分）被指定为以公允价值计量且其变动计入当期损益的金融工具的，企业应当在指定时将其账面价值（如有）与其公允价值之间的差额计入当期损益。如该金融工具是按照《企业会计准则第22号——金融工具确认和计量》第十八条分类为以公允价值计量且其变动计入其他综合收益的金融资产的，企业应当将之前计入其他综合收益的累计利得或损失转出，计入当期损益。","seq":33,"links":[{"doc_id":112,"tier":"L1","score":96,"rel_kind":"companion","target_seq":6,"target_art_no":"第7节","dir":"in","note":"指南详解（第7节）：锚定第三十四条（账面价值）"},{"doc_id":224,"tier":"L1","score":94,"rel_kind":"companion","target_seq":0,"target_art_no":"问1","dir":"in","note":"实施问答（问1）：锚定第三十四条（条文主题匹配）"},{"doc_id":224,"tier":"L1","score":94,"rel_kind":"companion","target_seq":1,"target_art_no":"问2","dir":"in","note":"实施问答（问2）：锚定第三十四条（条文主题匹配）"},{"doc_id":224,"tier":"L1","score":94,"rel_kind":"companion","target_seq":6,"target_art_no":"问7","dir":"in","note":"实施问答（问7）：锚定第三十四条（账面价值）"},{"doc_id":224,"tier":"L1","score":94,"rel_kind":"companion","target_seq":8,"target_art_no":"问9","dir":"in","note":"实施问答（问9）：锚定第三十四条（条文主题匹配）"},{"doc_id":224,"tier":"L1","score":94,"rel_kind":"companion","target_seq":11,"target_art_no":"问12","dir":"in","note":"实施问答（问12）：锚定第三十四条（条文主题匹配）"},{"doc_id":224,"tier":"L1","score":94,"rel_kind":"companion","target_seq":15,"target_art_no":"问16","dir":"in","note":"实施问答（问16）：锚定第三十四条（条文主题匹配）"},{"doc_id":224,"tier":"L1","score":94,"rel_kind":"companion","target_seq":17,"target_art_no":"问18","dir":"in","note":"实施问答（问18）：锚定第三十四条（条文主题匹配）"},{"doc_id":224,"tier":"L1","score":94,"rel_kind":"companion","target_seq":18,"target_art_no":"问19","dir":"in","note":"实施问答（问19）：锚定第三十四条（条文主题匹配）"},{"doc_id":224,"tier":"L1","score":94,"rel_kind":"companion","target_seq":19,"target_art_no":"问20","dir":"in","note":"实施问答（问20）：锚定第三十四条（条文主题匹配）"},{"doc_id":224,"tier":"L1","score":94,"rel_kind":"companion","target_seq":21,"target_art_no":"问22","dir":"in","note":"实施问答（问22）：锚定第三十四条（条文主题匹配）"},{"doc_id":224,"tier":"L1","score":94,"rel_kind":"companion","target_seq":23,"target_art_no":"问24","dir":"in","note":"实施问答（问24）：锚定第三十四条（条文主题匹配）"}]},{"id":691,"no":"第三十五条","heading":"","text":"同时满足下列条件的，企业应当对按照本准则第三十四条规定的金融工具（或其一定比例）终止以公允价值计量且其变动计入当期损益： （一）本准则第三十四条规定的条件不再适用，例如信用衍生工具或金融工具（或其一定比例）已到期、被出售、合同终止或已行使，或企业的风险管理目标发生变化，不再通过信用衍生工具进行风险管理。 （二）金融工具（或其一定比例）按照《企业会计准则第22号——金融工具确认和计量》的规定，仍然不满足以公允价值计量且其变动计入当期损益的金融工具的条件。 当企业对金融工具（或其一定比例）终止以公允价值计量且其变动计入当期损益时，该金融工具（或其一定比例）在终止时的公允价值应当作为其新的账面价值。同时，企业应当采用与该金融工具被指定为以公允价值计量且其变动计入当期损益之前相同的方法进行计量。","seq":34,"links":[{"doc_id":112,"tier":"L1","score":96,"rel_kind":"companion","target_seq":6,"target_art_no":"第7节","dir":"in","note":"指南详解（第7节）：锚定第三十五条（账面价值）"},{"doc_id":224,"tier":"L1","score":94,"rel_kind":"companion","target_seq":10,"target_art_no":"问11","dir":"in","note":"实施问答（问11）：锚定第三十五条（条文主题匹配）"},{"doc_id":224,"tier":"L1","score":94,"rel_kind":"companion","target_seq":13,"target_art_no":"问14","dir":"in","note":"实施问答（问14）：锚定第三十五条（条文主题匹配）"},{"doc_id":224,"tier":"L1","score":94,"rel_kind":"companion","target_seq":24,"target_art_no":"问25","dir":"in","note":"实施问答（问25）：锚定第三十五条（条文主题匹配）"},{"doc_id":37,"tier":"L3","score":72,"rel_kind":"cites","target_seq":69,"target_art_no":"第七十条","dir":"in","note":"正文显式引用《企业会计准则第24号——套期会计》第35条"},{"doc_id":22,"tier":"L3","score":64,"rel_kind":"cites","target_seq":0,"target_art_no":"第一条","dir":"out","note":"正文显式引用《企业会计准则第22号——金融工具确认和计量》"}]},{"id":692,"no":"第三十六条","heading":"","text":"本准则施行日之前套期会计处理与本准则要求不一致的，企业不作追溯调整，但本准则第三十七条所规定的情况除外。 在本准则施行日，企业应当按照本准则的规定对所存在的套期关系进行评估。在符合本准则规定的情况下可以进行再平衡，再平衡后仍然符合本准则规定的运用套期会计方法条件的，将其视为持续的套期关系，并将再平衡所产生的相关利得或损失计入当期损益。","seq":35},{"id":693,"no":"第三十七条","heading":"","text":"下列情况下，企业应当按照本准则的规定，对在比较期间最早的期初已经存在的、以及在此之后被指定的套期关系进行追溯调整： （一）企业将期权的内在价值和时间价值分开，只将期权的内在价值变动指定为套期工具。 （二）本准则第二十一条（二）规定的情形。 此外，企业将远期合同的远期要素和即期要素分开、只将即期要素的价值变动指定为套期工具的，或者将金融工具的外汇基差单独分拆、只将排除外汇基差后的金融工具指定为套期工具的，可以按照与本准则期权时间价值相同的处理方式对远期合同的远期要素和金融工具的外汇基差的会计处理进行追溯调整。如果选择追溯调整，企业应当对所有满足该选择条件的套期关系进行追溯调整。","seq":36,"links":[{"doc_id":112,"tier":"L1","score":96,"rel_kind":"companion","target_seq":7,"target_art_no":"第8节","dir":"in","note":"指南详解（第8节）：锚定第三十七条（条文主题匹配）"}]},{"id":694,"no":"第三十八条","heading":"","text":"本准则自2018年1月1日起施行。","seq":37}]});
